function indexOf(definition: ReferenceFixtureProps['definition']): number {
  const match = definition.variantSlug.match(/-(\d+)$/)
  return Number(match?.[1] ?? 1)
}

function descriptionFor(definition: ReferenceFixtureProps['definition']): string {
  return descriptions[definition.category]?.[indexOf(definition) - 1] ?? definition.description
}

function FixtureHeader({ definition, icon, tone = 'neutral', actions = true }: { definition: ReferenceFixtureProps['definition']; icon?: React.ReactNode; tone?: ReferenceTone; actions?: boolean }) {
  return <header className="rb-blueprint-header"><div className="rb-blueprint-title"><span className="rb-blueprint-icon">{icon ?? <WandSparkles size={14} />}</span><div><strong>{definition.title}</strong><small>{descriptionFor(definition)}</small></div></div><div className="rb-blueprint-header-actions">{actions && <><ReferenceBadge tone={tone}>{tone === 'running' ? 'Running' : tone === 'success' ? 'Ready' : 'Fixture'}</ReferenceBadge><button type="button" className="rb-blueprint-icon-button" aria-label="More actions"><MoreHorizontal size={14} /></button></>}</div></header>
}

export function ActivityBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = ACTIVITY_PREVIEWS[definition.variantSlug] ?? {
    heading: definition.title,
    status: 'Running',
    summary: 'Current activity',
    steps: [{ title: 'Inspect workspace', meta: 'working', status: 'running' as const }],
    tabs: ['Timeline', 'Details'] as const,
  }
  const tabs = config.tabs ?? ['Timeline', 'Details']
  const [tab, setTab] = useState(tabs[0] ?? 'Timeline')
  const [paused, setPaused] = useState(false)
  const [expanded, setExpanded] = useState(true)
  const statusTone: ReferenceTone = paused || config.status.toLowerCase().includes('failed') ? 'warning' : config.status.toLowerCase().includes('succeeded') ? 'success' : 'running'
  const isLog = tab === 'Terminal' || tab === 'Log'
  const timelineItems = config.steps.map((step, index) => ({ ...step, id: `${definition.variantSlug}-${index}` }))
  return <ReferenceSurface className={`rb-blueprint rb-activity-blueprint rb-activity-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={{ ...definition, title: config.heading }} icon={<Activity size={14} />} tone={paused ? 'warning' : statusTone} /><div className="rb-blueprint-toolbar"><ReferenceTabs tabs={tabs} value={tab} onChange={setTab} /><ReferenceButton variant="ghost" onClick={() => setPaused((value) => !value)}>{paused ? <Play size={12} /> : <Pause size={12} />}{paused ? 'Resume' : 'Pause'}</ReferenceButton></div>{isLog ? <div className="rb-terminal-log" role="log" aria-live="polite">{config.steps.map((step) => <code key={step.title} className={step.status === 'warning' || step.status === 'danger' ? 'warning' : ''}>{step.meta} {step.title}</code>)}</div> : tab === 'JSON' ? <pre className="rb-blueprint-code">{JSON.stringify({ runId: 'run_alpha', status: paused ? 'paused' : config.status, summary: config.summary }, null, 2)}</pre> : <><div className="rb-activity-summary"><ReferenceMetric label="Status" value={paused ? 'Paused' : config.status} detail={config.summary} tone={paused ? 'warning' : statusTone} /><ReferenceMetric label="Steps" value={String(config.steps.length)} detail={variant === 6 ? 'parallel lanes' : 'recorded'} /><ReferenceMetric label="Current action" value={timelineItems.find((step) => step.status === 'running')?.title ?? timelineItems[0]?.title ?? 'Ready'} detail={paused ? 'paused' : 'live'} tone={paused ? 'warning' : 'running'} /></div><div className="rb-blueprint-section-heading"><strong>{variant === 4 ? 'Run history' : variant === 7 ? 'Inputs / outputs / error' : config.summary}</strong><ReferenceButton variant="ghost" onClick={() => setExpanded((value) => !value)}>{expanded ? 'Collapse' : 'Expand'}</ReferenceButton></div>{expanded && <ReferenceTimeline items={timelineItems} />}</>}</ReferenceSurface>
}

export function ToolCallsBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = TOOL_CALL_PREVIEWS[definition.variantSlug] ?? { heading: definition.title, status: 'Ready', command: 'inspect_workspace', detail: 'Arguments and result', lines: ['workspace scan complete'], mode: 'call' as const }
  const [expanded, setExpanded] = useState(true)
  const [tab, setTab] = useState(config.mode === 'terminal' ? 'stdout' : 'Result')
  const icon = config.mode === 'terminal' ? <Terminal size={14} /> : config.mode === 'web' ? <Globe2 size={14} /> : config.mode === 'diff' ? <FileDiff size={14} /> : config.mode === 'permission' ? <ShieldCheck size={14} /> : <Code2 size={14} />
  const tone: ReferenceTone = config.mode === 'permission' ? 'warning' : config.status.toLowerCase().includes('fail') ? 'danger' : config.status.toLowerCase().includes('running') ? 'running' : 'success'
  return <ReferenceSurface className={`rb-blueprint rb-tool-blueprint rb-tool-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={{ ...definition, title: config.heading }} icon={icon} tone={tone} /><div className="rb-tool-call-row"><div className="rb-tool-call-leading"><span className={`rb-tool-call-status ${tone}`}><Check size={12} /></span><div><strong>{config.command}</strong><small>{config.status} · {config.detail}</small></div></div><ReferenceButton variant="ghost" onClick={() => setExpanded((value) => !value)} aria-expanded={expanded}>{expanded ? <ChevronDown size={13} /> : <ArrowDown size={13} />}</ReferenceButton></div>{expanded && <div className="rb-tool-call-detail">{config.mode === 'permission' ? <div className="rb-permission-grid"><ReferenceBadge tone="warning">Scope requested</ReferenceBadge><p>{config.detail}</p><ReferenceButton variant="danger">Reject</ReferenceButton><ReferenceButton variant="primary">Approve</ReferenceButton></div> : config.mode === 'web' ? <ReferenceList>{config.lines.map((line, index) => <ReferenceListRow key={line} title={line.split(' · ')[0] ?? line} meta={line.includes(' · ') ? line.slice(line.indexOf(' · ') + 3) : `source ${index + 1}`} badge={<ReferenceBadge tone="success">source</ReferenceBadge>} />)}</ReferenceList> : config.mode === 'diff' ? <pre className="rb-diff-view">{config.lines.map((line) => <span key={line} className={line.startsWith('-') ? 'remove' : line.startsWith('+') ? 'add' : undefined}>{line}</span>)}</pre> : config.mode === 'terminal' ? <><ReferenceTabs tabs={['stdout', 'stderr']} value={tab} onChange={setTab} /><pre className="rb-blueprint-code">{tab === 'stdout' ? config.lines.join('\n') : 'stderr empty'}</pre></> : <><ReferenceTabs tabs={['Result', 'Arguments']} value={tab} onChange={setTab} /><pre className="rb-blueprint-code">{tab === 'Result' ? config.lines.join('\n') : JSON.stringify({ command: config.command, detail: config.detail }, null, 2)}</pre></>}</div>}</ReferenceSurface>
}

export function ApprovalBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = APPROVAL_PREVIEWS[definition.variantSlug] ?? { heading: definition.title, status: 'Needs approval', title: 'Review requested action', description: 'Review the declared scope before continuing.', items: [] }
  const [decision, setDecision] = useState<'pending' | 'allowed' | 'denied'>('pending')
  const isQueue = variant === 3 || variant === 6
  const tone: ReferenceTone = decision === 'pending' ? 'warning' : decision === 'allowed' ? 'success' : 'danger'
  return <ReferenceSurface className={`rb-blueprint rb-approval-blueprint rb-approval-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={{ ...definition, title: config.heading }} icon={<ShieldCheck size={14} />} tone={tone} /><div className="rb-approval-risk"><div><ReferenceBadge tone={tone}>{decision === 'pending' ? config.status : decision}</ReferenceBadge><h3>{config.title}</h3><p>{config.description}</p></div><div className="rb-approval-actions">{decision === 'pending' ? <><ReferenceButton variant="danger" onClick={() => setDecision('denied')}>Reject</ReferenceButton><ReferenceButton variant="primary" onClick={() => setDecision('allowed')}>Approve</ReferenceButton></> : <ReferenceButton variant="secondary" onClick={() => setDecision('pending')}>Review again</ReferenceButton>}</div></div>{(isQueue || config.items.length > 0) && <ReferenceList>{config.items.map((item, index) => <ReferenceListRow key={item} title={item} meta={decision === 'pending' ? 'pending · review details' : decision} badge={<ReferenceBadge tone={index === 0 && decision === 'pending' ? 'danger' : tone}>{decision === 'pending' ? 'pending' : decision}</ReferenceBadge>} />)}</ReferenceList>}</ReferenceSurface>
}

export function PlanBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = PLAN_PREVIEWS[definition.variantSlug] ?? { heading: definition.title, status: 'In progress', summary: 'Task plan', steps: ['Inspect workspace', 'Draft changes', 'Run verification'] }
  const [selected, setSelected] = useState(config.steps[0] ?? '')
  const completed = config.steps.filter((step) => /done|completed/i.test(step)).length
  return <ReferenceSurface className={`rb-blueprint rb-plan-blueprint rb-plan-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={{ ...definition, title: config.heading }} icon={<Check size={14} />} tone={config.status.toLowerCase().includes('failed') ? 'danger' : 'running'} /><div className="rb-plan-progress"><div><strong>{config.summary}</strong><small>{config.status}</small></div><span><b style={{ width: `${Math.max(12, Math.round((completed / Math.max(1, config.steps.length)) * 100))}%` }} /></span></div><ReferenceList>{config.steps.map((step) => { const done = /done|completed/i.test(step); const failed = /retry|failed/i.test(step); const running = /running|current/i.test(step); return <ReferenceListRow key={step} title={step.replace(/\s+·.*$/, '')} meta={step.includes('·') ? step.slice(step.indexOf('·') + 1).trim() : running ? 'running · current' : done ? 'completed' : 'queued'} selected={selected === step} onClick={() => setSelected(step)} badge={<ReferenceBadge tone={failed ? 'danger' : done ? 'success' : running ? 'running' : 'neutral'}>{failed ? 'retry' : done ? 'done' : running ? 'now' : 'next'}</ReferenceBadge>} />})}</ReferenceList><div className="rb-plan-footer"><ReferenceButton variant="ghost"><Plus size={12} /> Add</ReferenceButton><ReferenceButton variant="secondary"><ArrowUp size={12} /> Reorder</ReferenceButton><ReferenceButton variant="primary">{variant === 6 ? 'Run plan' : 'Continue'}</ReferenceButton></div></ReferenceSurface>
}

export function UsageBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = USAGE_PREVIEWS[definition.variantSlug] ?? { heading: definition.title, summary: 'Usage overview', metrics: [['Tokens', '0', 'recorded'], ['Requests', '0', 'recorded'], ['Cost', '$0', 'recorded']] as readonly [string, string, string][], rows: [], tabs: ['7d'] }
  const [range, setRange] = useState(config.tabs[0] ?? '7d')
  return <ReferenceSurface className={`rb-blueprint rb-usage-blueprint rb-usage-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={{ ...definition, title: config.heading }} icon={<Activity size={14} />} tone="accent" /><div className="rb-blueprint-toolbar"><ReferenceTabs tabs={config.tabs} value={range} onChange={setRange} /><ReferenceButton variant="ghost"><DownloadIcon /> Export</ReferenceButton></div><p className="rb-usage-summary">{config.summary}</p><div className="rb-usage-metrics">{config.metrics.map(([label, value, detail]) => <ReferenceMetric key={label} label={label} value={value} detail={detail} tone={label.toLowerCase().includes('cost') || label.toLowerCase().includes('spend') ? 'accent' : label.toLowerCase().includes('limit') ? 'warning' : 'neutral'} />)}</div><div className="rb-usage-bar"><span>{variant === 3 ? 'Rolling window' : 'Context window'}</span><strong>{variant === 3 ? '412 / 500 req' : variant === 8 ? '92% used' : '18.4k / 128k'}</strong><i><b style={{ width: variant === 3 ? '82%' : variant === 8 ? '92%' : '38%' }} /></i></div>{config.rows.length > 0 && <ReferenceList>{config.rows.map((row, index) => <ReferenceListRow key={row} title={row.split(' · ')[0] ?? row} meta={row.includes(' · ') ? row.slice(row.indexOf(' · ') + 3) : `row ${index + 1}`} badge={<span className="rb-usage-share" style={{ '--share': `${Math.max(18, 58 - index * 10)}%` } as React.CSSProperties}>{Math.max(18, 58 - index * 10)}%</span>} />)}</ReferenceList>}</ReferenceSurface>
}

function DownloadIcon() { return <ArrowDown size={12} /> }

export function ShellBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const [active, setActive] = useState('Overview')
  const [menuOpen, setMenuOpen] = useState(false)
  const nav = variant % 3 === 0 ? ['Overview', 'Threads', 'Activity', 'Settings'] : ['Home', 'Sessions', 'Files', 'Activity']
  return <ReferenceSurface className={`rb-blueprint rb-shell-blueprint rb-shell-variant-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><div className="rb-shell-sidebar"><div className="rb-shell-brand"><span className="rb-blueprint-icon"><WandSparkles size={13} /></span><strong>hbar</strong></div>{nav.map((item) => <button type="button" key={item} className={active === item ? 'selected' : ''} onClick={() => setActive(item)}><span className="rb-shell-nav-icon"><CircleDashed size={12} /></span>{item}<small>{item === 'Sessions' ? '12' : ''}</small></button>)}<div className="rb-shell-sidebar-footer"><button type="button" onClick={() => setMenuOpen((value) => !value)}><Users size={12} />Workspace <ChevronDown size={11} /></button>{menuOpen && <div className="rb-shell-menu" role="menu"><button type="button">Meridian Labs</button><button type="button">Personal</button></div>}</div></div><div className="rb-shell-content"><header><div><small>Workspace / {active}</small><h3>{definition.title}</h3></div><div className="rb-shell-header-actions"><button type="button" aria-label="Search"><Search size={13} /></button><button type="button" aria-label="Settings"><Settings2 size={13} /></button></div></header><div className="rb-shell-grid"><ReferenceMetric label="Active runs" value="03" detail="+1 today" tone="running" /><ReferenceMetric label="Workspace files" value="128" detail="synced" /><ReferenceMetric label="Usage" value="42%" detail="of budget" tone="accent" /></div><ReferenceSurface kind="card" className="rb-shell-content-card"><div className="rb-blueprint-section-heading"><strong>{variant === 4 ? 'Context panel' : active}</strong><ReferenceButton variant="ghost"><MoreHorizontal size={13} /></ReferenceButton></div><p>Stable content region with a contextual secondary panel and responsive navigation.</p></ReferenceSurface></div>{variant === 4 && <aside className="rb-shell-context"><strong>Context</strong><small>Three-column frame</small><ReferenceList><ReferenceListRow title="Current run" meta="running · 00:18" /><ReferenceListRow title="Pinned files" meta="4 sources" /></ReferenceList></aside>}</ReferenceSurface>
}

function initials(name: string): string {
  return name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase()
}

function CardBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = CARD_PREVIEWS[`card-${variant}`] ?? { heading: definition.title, description: definition.description, kind: 'metrics' as const, statLabels: [['Records', '12'], ['Ready', '100%']] as readonly [string, string][] }
  const [connected, setConnected] = useState<string[]>(['Imani Hale'])
  const [completed, setCompleted] = useState<number[]>([0])
  const [range, setRange] = useState('30d')
  const [selectedFile, setSelectedFile] = useState(config.names?.[0] ?? '')
  const [bookmarked, setBookmarked] = useState<string[]>([])
  const [selectedPlan, setSelectedPlan] = useState('Growth')
  const [sent, setSent] = useState(false)
  const stats = config.statLabels ?? [['Active', '12'], ['Updated', 'Today'], ['Health', 'Good']]
  const toggleName = (name: string) => setConnected((current) => current.includes(name) ? current.filter((item) => item !== name) : [...current, name])
  const toggleStep = (step: number) => setCompleted((current) => current.includes(step) ? current.filter((item) => item !== step) : [...current, step])
  const toggleBookmark = (item: string) => setBookmarked((current) => current.includes(item) ? current.filter((entry) => entry !== item) : [...current, item])
  const cardClass = `rb-blueprint rb-card-blueprint rb-card-${config.kind} rb-card-variant-${variant}`
  return <ReferenceSurface className={cardClass} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}>
    <FixtureHeader definition={{ ...definition, title: config.heading, description: config.description }} icon={config.kind === 'members' || config.kind === 'profile' ? <Users size={14} /> : config.kind === 'files' ? <Folder size={14} /> : <WandSparkles size={14} />} tone="neutral" />
    {config.kind === 'members' && <>
      <div className="rb-card-member-grid">{(config.names ?? []).map((name, index) => <article className="rb-member-card" key={name}><div className="rb-member-card-avatar"><span>{initials(name)}</span><i className={index === 1 || index === 4 ? 'online' : ''} /></div><strong>{name}</strong><small>{['Product Lead · Lisbon', 'Staff Engineer · Berlin', 'Design Director · New York', 'Data Scientist · Toronto', 'Support Manager · São Paulo', 'Solutions Architect · Singapore'][index]}</small><p>{['Runs discovery and roadmap for the payments surface.', 'Owns the ledger service and the move to event sourcing.', 'Sets the visual system and reviews every shipped surface.', 'Builds the forecasting models behind the revenue dashboard.', 'Leads the escalation desk across three regions.', 'Pairs with enterprise accounts through their first integration.'][index]}</p><ReferenceButton variant={connected.includes(name) ? 'secondary' : 'ghost'} onClick={() => toggleName(name)}>{connected.includes(name) ? 'Connected' : 'Connect'}</ReferenceButton></article>)}</div>
      <div className="rb-card-stat-strip">{stats.map(([label, value]) => <ReferenceMetric key={label} label={label} value={value} />)}</div>
    </>}
    {config.kind === 'integrations' && <div className="rb-card-integration-list">{(config.names ?? []).map((name, index) => <div className="rb-integration-row" key={name}><span className="rb-integration-logo">{initials(name)}</span><div><strong>{name}</strong><small>{['Payments and subscriptions', 'Support and customer records', 'Accounts and contacts', 'Files and shared assets'][index]}</small></div><button type="button" role="switch" aria-checked={connected.includes(name)} className={connected.includes(name) ? 'on' : ''} onClick={() => toggleName(name)}><i /></button></div>)}</div>}
    {config.kind === 'onboarding' && <div className="rb-card-onboarding"><div className="rb-card-onboarding-summary"><strong>{completed.length} of 3 complete</strong><ReferenceButton variant="ghost" onClick={() => setCompleted([])}>Reset</ReferenceButton></div><div className="rb-card-onboarding-grid">{['Create your workspace', 'Invite a teammate', 'Connect an integration'].map((step, index) => <button type="button" className={completed.includes(index) ? 'done' : ''} key={step} onClick={() => toggleStep(index)}><span>{completed.includes(index) ? <Check size={13} /> : index + 1}</span><strong>{step}</strong><small>{completed.includes(index) ? 'Complete' : 'Not started'}</small></button>)}</div></div>}
    {config.kind === 'agenda' && <div className="rb-card-agenda-list">{(config.names ?? []).map((item, index) => <article key={item}><time><strong>{['14', '16', '21'][index]}</strong><small>{['JUN', 'JUN', 'JUN'][index]}</small></time><div><strong>{item}</strong><small>{['09:30 · Atlas room', '13:00 · Design studio', '16:45 · Video call'][index]}</small><p>{['Priya, Ari and 4 others', 'Sam, Dana and 2 others', 'Customer success team'][index]}</p></div><ReferenceButton variant={index === 0 ? 'primary' : 'secondary'}>{index === 0 ? 'Going' : 'RSVP'}</ReferenceButton></article>)}</div>}
    {config.kind === 'plans' && <div className="rb-card-plan-grid">{(config.names ?? []).map((plan, index) => <article className={selectedPlan === plan ? 'selected' : ''} key={plan}><small>{index === 1 ? 'MOST POPULAR' : 'PLAN'}</small><h3>{plan}</h3><strong>{['$0', '$24', '$80'][index]}<em>/ seat</em></strong><p>{['For trying the workspace', 'For growing teams', 'For larger organizations'][index]}</p><ul>{['Unlimited projects', 'Shared activity', 'Priority support'].map((item) => <li key={item}><Check size={12} /> {item}</li>)}</ul><ReferenceButton variant={selectedPlan === plan ? 'primary' : 'secondary'} onClick={() => setSelectedPlan(plan)}>{selectedPlan === plan ? 'Selected' : config.actionLabel}</ReferenceButton></article>)}</div>}
    {config.kind === 'metrics' && <><div className="rb-card-range-tabs"><ReferenceTabs tabs={['7d', '30d', '90d']} value={range} onChange={setRange} /><span>{range} · compared with previous period</span></div><div className="rb-card-metric-grid">{stats.map(([label, value], index) => <ReferenceMetric key={label} label={label} value={value} detail={['+8.4%', 'steady', '+2.1%'][index] ?? 'updated'} tone={index === 0 ? 'accent' : 'neutral'} />)}</div><div className="rb-card-sparkline" aria-label="Account metric chart">{[26, 42, 33, 56, 48, 72, 68, 82, 76, 94].map((height, index) => <i key={index} style={{ height: `${height}%` }} />)}</div></>}
    {config.kind === 'changelog' && <div className="rb-card-changelog-list">{(config.names ?? []).map((version, index) => <article key={version}><small>RELEASE · {['JUN 24', 'JUN 12', 'MAY 30'][index]}</small><h3>{version} {['Shared session views', 'Faster search indexing', 'Saved filter presets'][index]}</h3><p>{['Pin a view and share it with the whole workspace.', 'Search now returns ranked results as you type.', 'Keep a set of filters ready for the next review.'][index]}</p><span>{['Sam Rivera', 'Imani Hale', 'Dana Okafor'][index]}</span><button type="button" aria-label={`${bookmarked.includes(version) ? 'Remove' : 'Add'} bookmark for ${version}`} onClick={() => toggleBookmark(version)}>{bookmarked.includes(version) ? '★' : '☆'}</button></article>)}</div>}
    {config.kind === 'files' && <><div className="rb-card-file-toolbar"><span>{selectedFile ? `1 selected · ${selectedFile}` : 'Select a file'}</span><ReferenceButton variant="ghost"><MoreHorizontal size={13} /> Actions</ReferenceButton></div><div className="rb-card-file-grid">{(config.names ?? []).map((file) => <button type="button" className={selectedFile === file ? 'selected' : ''} key={file} onClick={() => setSelectedFile(file)}><span className="rb-file-preview"><File size={18} /></span><strong>{file}</strong><small>{file.endsWith('.pdf') ? 'PDF · 3.4 MB' : file.endsWith('.csv') ? 'CSV · 44 KB' : 'Image · 1.2 MB'}</small></button>)}</div></>}
    {config.kind === 'profile' && <div className="rb-card-profile"><div className="rb-profile-hero"><div className="rb-profile-avatar">SR</div><div><h3>{config.heading}</h3><p>{config.description}</p><div className="rb-profile-tags">{(config.names ?? []).map((tag) => <span key={tag}>{tag}</span>)}</div></div><ReferenceButton variant={sent ? 'secondary' : 'primary'} onClick={() => setSent((value) => !value)}>{sent ? 'Message sent' : config.actionLabel}</ReferenceButton></div><div className="rb-card-stat-strip">{stats.map(([label, value]) => <ReferenceMetric key={label} label={label} value={value} />)}</div></div>}
    {config.kind === 'balance' && <div className="rb-card-balance"><div className="rb-balance-head"><small>AVAILABLE BALANCE</small><strong>{stats[0]?.[1] ?? '$12,480.20'}</strong><span>+12.4% this month</span></div><div className="rb-balance-split">{stats.slice(1).map(([label, value]) => <ReferenceMetric key={label} label={label} value={value} />)}</div><div className="rb-card-activity"><small>RECENT ACTIVITY</small><ReferenceList><ReferenceListRow title="Acme Logistics" meta="Received · Today" badge={<span className="rb-card-money-positive">+$840.00</span>} /><ReferenceListRow title="Workspace seats" meta="Paid · Yesterday" badge={<span>−$240.00</span>} /></ReferenceList></div><div className="rb-card-actions"><ReferenceButton variant="primary" onClick={() => setSent((value) => !value)}>{sent ? 'Transfer ready' : config.actionLabel}</ReferenceButton><ReferenceButton variant="secondary">Add money</ReferenceButton></div></div>}
    {config.kind === 'invoice' && <div className="rb-card-invoice"><div className="rb-invoice-head"><div><small>INVOICE · JUN 24, 2026</small><h3>{config.heading}</h3></div><ReferenceBadge tone="success">Paid</ReferenceBadge></div><ReferenceList>{(config.names ?? []).map((item, index) => <ReferenceListRow key={item} title={item} meta={['12 seats · $960.00', 'Usage · $184.00', 'Team support · $140.00'][index] ?? ''} badge={<span>{['$960.00', '$184.00', '$140.00'][index] ?? '$0.00'}</span>} />)}</ReferenceList><div className="rb-invoice-total"><span>Total</span><strong>{stats[0]?.[1] ?? '$1,284.00'}</strong></div><ReferenceButton variant="secondary" onClick={() => setSent((value) => !value)}><ArrowDown size={12} /> {sent ? 'Downloaded' : config.actionLabel}</ReferenceButton></div>}
  </ReferenceSurface>
}

const fallbackTableRows = DATA_TABLE_PREVIEWS['data-table-1']!.rows

function DataTableBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const config = DATA_TABLE_PREVIEWS[`data-table-${variant}`] ?? DATA_TABLE_PREVIEWS['data-table-1']!
  const rows = config.rows.length > 0 ? config.rows : fallbackTableRows
  const [query, setQuery] = useState('')
  const [selectedPlans, setSelectedPlans] = useState<string[]>([])
  const [selectedRows, setSelectedRows] = useState<string[]>([])
  const [columnsOpen, setColumnsOpen] = useState(false)
  const [expanded, setExpanded] = useState<string | undefined>()
  const [selectedRow, setSelectedRow] = useState(rows[0]?.account)
  const [density, setDensity] = useState<'comfortable' | 'compact'>('comfortable')
  const [tableState, setTableState] = useState<'ready' | 'loading' | 'empty' | 'error'>('ready')
  const [editing, setEditing] = useState<string | undefined>()
  const [visibleColumns, setVisibleColumns] = useState(['owner', 'plan', 'status', 'region', 'mrr', 'renewal'])
  const filteredRows = rows.filter((row) => {
    const matchesQuery = `${row.account} ${row.owner} ${row.region}`.toLowerCase().includes(query.toLowerCase())
    const matchesPlan = selectedPlans.length === 0 || selectedPlans.includes(row.plan)
    return matchesQuery && matchesPlan
  })
  const togglePlan = (plan: string) => setSelectedPlans((current) => current.includes(plan) ? current.filter((item) => item !== plan) : [...current, plan])
  const toggleRow = (account: string) => setSelectedRows((current) => current.includes(account) ? current.filter((item) => item !== account) : [...current, account])
  const toggleColumn = (column: string) => setVisibleColumns((current) => current.includes(column) ? current.filter((item) => item !== column) : [...current, column])
  const statusTone = (status: string): ReferenceTone => status === 'Active' ? 'success' : status === 'Paused' ? 'warning' : 'danger'
  const isMobileCards = variant === 8
  return <ReferenceSurface className={`rb-blueprint rb-data-table-blueprint rb-data-table-${variant} ${density}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}>
    <FixtureHeader definition={{ ...definition, title: config.heading, description: config.description }} icon={<ListFilter size={14} />} tone={tableState === 'error' ? 'danger' : 'neutral'} />
    <div className="rb-table-heading"><div><h3>{config.description}</h3><small>{filteredRows.length} of {rows.length} accounts</small></div><ReferenceButton variant="secondary"><ArrowDown size={12} /> Export</ReferenceButton></div>
    <div className="rb-data-table-toolbar"><label><Search size={12} /><input aria-label="Search accounts" placeholder="Search accounts" value={query} onChange={(event) => setQuery(event.target.value)} /></label><div className="rb-data-table-facets">{config.filters.map((filter) => <label key={filter}><input type="checkbox" checked={filter === 'All plans' ? selectedPlans.length === 0 : selectedPlans.includes(filter)} onChange={() => filter === 'All plans' ? setSelectedPlans([]) : togglePlan(filter)} />{filter}</label>)}</div><div className="rb-columns-control"><ReferenceButton variant="ghost" onClick={() => setColumnsOpen((value) => !value)}><SlidersHorizontal size={12} /> Columns</ReferenceButton>{columnsOpen && <div className="rb-columns-menu" role="menu">{['owner', 'plan', 'status', 'region', 'mrr', 'renewal'].map((column) => <label key={column}><input type="checkbox" checked={visibleColumns.includes(column)} onChange={() => toggleColumn(column)} />{column[0]!.toUpperCase() + column.slice(1)}</label>)}</div>}</div>{variant === 5 && <ReferenceButton variant="ghost" onClick={() => setDensity((value) => value === 'comfortable' ? 'compact' : 'comfortable')}>{density === 'comfortable' ? 'Compact' : 'Comfortable'}</ReferenceButton>}</div>
    {selectedRows.length > 0 && <div className="rb-table-selection-bar"><strong>{selectedRows.length} selected</strong><ReferenceButton variant="ghost" onClick={() => setSelectedRows([])}>Clear</ReferenceButton><ReferenceButton variant="danger">Archive</ReferenceButton></div>}
    {tableState === 'loading' && <div className="rb-table-state"><span className="rb-table-skeleton" /><span className="rb-table-skeleton" /><span className="rb-table-skeleton" /></div>}
    {tableState === 'empty' && <ReferenceEmptyState title="No accounts found" description="Try a broader search or clear one of the active facets." action={<ReferenceButton variant="secondary" onClick={() => { setQuery(''); setSelectedPlans([]); setTableState('ready') }}>Clear filters</ReferenceButton>} />}
    {tableState === 'error' && <ReferenceEmptyState title="Unable to load accounts" description="The request timed out before the table could be refreshed." action={<ReferenceButton variant="primary" onClick={() => setTableState('ready')}>Retry</ReferenceButton>} />}
    {tableState === 'ready' && <>
      <div className={`rb-data-table-scroll ${isMobileCards ? 'force-cards' : ''}`}><table><thead><tr><th className="rb-table-select"><input type="checkbox" aria-label="Select all accounts" checked={selectedRows.length === filteredRows.length && filteredRows.length > 0} onChange={() => setSelectedRows(selectedRows.length === filteredRows.length ? [] : filteredRows.map((row) => row.account))} /></th><th>Account</th>{visibleColumns.includes('owner') && <th>Owner</th>}{visibleColumns.includes('plan') && <th>Plan</th>}{visibleColumns.includes('status') && <th>Status</th>}{visibleColumns.includes('region') && <th>Region</th>}{visibleColumns.includes('mrr') && <th>MRR</th>}{visibleColumns.includes('renewal') && <th>Renewal</th>}</tr></thead><tbody>{filteredRows.map((row) => <Fragment key={row.account}><tr className={selectedRow === row.account ? 'selected' : ''} onClick={() => { setSelectedRow(row.account); if (variant === 4) setExpanded((current) => current === row.account ? undefined : row.account) }}><td className="rb-table-select"><input type="checkbox" aria-label={`Select ${row.account}`} checked={selectedRows.includes(row.account)} onChange={() => toggleRow(row.account)} onClick={(event) => event.stopPropagation()} /></td><th>{row.account}</th>{visibleColumns.includes('owner') && <td>{row.owner}</td>}{visibleColumns.includes('plan') && <td>{variant === 3 && editing === `${row.account}-plan` ? <input autoFocus defaultValue={row.plan} onBlur={() => setEditing(undefined)} onKeyDown={(event) => { if (event.key === 'Enter') setEditing(undefined) }} /> : <button type="button" className="rb-table-inline-value" onClick={(event) => { event.stopPropagation(); if (variant === 3) setEditing(`${row.account}-plan`) }}>{row.plan}</button>}</td>}{visibleColumns.includes('status') && <td><ReferenceBadge tone={statusTone(row.status)}>{row.status}</ReferenceBadge></td>}{visibleColumns.includes('region') && <td>{row.region}</td>}{visibleColumns.includes('mrr') && <td className="numeric">{row.mrr}</td>}{visibleColumns.includes('renewal') && <td>{row.renewal}</td>}<td className="rb-table-action"><button type="button" aria-label={`More actions for ${row.account}`}><MoreHorizontal size={13} /></button></td></tr>{variant === 4 && expanded === row.account && <tr className="rb-table-expanded"><td colSpan={9}><strong>{row.account}</strong><p>Owner {row.owner} · renewal {row.renewal} · {row.region}. Recent activity and account notes stay inline.</p></td></tr>}</Fragment>)}</tbody></table><div className="rb-table-mobile-list">{filteredRows.map((row) => <button type="button" className={selectedRow === row.account ? 'selected' : ''} key={row.account} onClick={() => setSelectedRow(row.account)}><strong>{row.account}</strong><span>{row.mrr}</span><small>{row.status} · {row.plan} · Renews {row.renewal}</small></button>)}</div></div>
      <footer className="rb-table-footer"><span>Showing {filteredRows.length} of {rows.length} accounts</span><div><ReferenceButton variant="ghost" disabled>Previous</ReferenceButton><ReferenceButton variant="secondary">1</ReferenceButton><ReferenceButton variant="ghost" disabled>Next</ReferenceButton></div></footer>
    </>}
    {variant === 6 && selectedRow && <aside className="rb-table-detail"><div><strong>{selectedRow}</strong><button type="button" aria-label="Close detail" onClick={() => setSelectedRow(undefined)}><ChevronDown size={13} /></button></div><p>Account detail follows the selected row and keeps the table context visible.</p><ReferenceMetric label="Current MRR" value={rows.find((row) => row.account === selectedRow)?.mrr ?? '—'} detail="monthly recurring revenue" tone="accent" /></aside>}
    {variant === 7 && <div className="rb-table-state-actions"><ReferenceButton variant="ghost" onClick={() => setTableState('loading')}>Loading</ReferenceButton><ReferenceButton variant="ghost" onClick={() => setTableState('empty')}>Empty</ReferenceButton><ReferenceButton variant="ghost" onClick={() => setTableState('error')}>Error</ReferenceButton></div>}
  </ReferenceSurface>
}

export function DataBlueprint({ definition, viewport, onInteraction, refreshKey }: ReferenceFixtureProps) {
  void refreshKey
  if (definition.category === 'card') return <CardBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'data-table') return <DataTableBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  return <GenericDataBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
}

function GenericDataBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const [selected, setSelected] = useState('Atlas / Balanced')
  const [filter, setFilter] = useState('')
  const rows = useMemo(() => ['Atlas / Balanced', 'Atlas / Fast', 'Nova / Reasoning', 'Workspace fallback'].filter((row) => row.toLowerCase().includes(filter.toLowerCase())), [filter])
  return <ReferenceSurface className="rb-blueprint rb-data-blueprint" onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={definition} icon={variant % 2 === 0 ? <Folder size={14} /> : <ListFilter size={14} />} tone="neutral" /><div className="rb-data-toolbar"><label><Search size={12} /><input aria-label="Filter rows" placeholder="Filter" value={filter} onChange={(event) => setFilter(event.target.value)} /></label><ReferenceButton variant="ghost"><SlidersHorizontal size={12} /> Filters</ReferenceButton><ReferenceButton variant="ghost"><Copy size={12} /> Export</ReferenceButton></div>{definition.category === 'analytics' || definition.category === 'dashboard' ? <div className="rb-data-chart" aria-label="Deterministic chart"><div className="rb-chart-bars">{[42, 68, 55, 76, 64, 84, 72].map((height, index) => <i key={index} style={{ height: `${height}%` }} />)}</div><div className="rb-chart-axis"><span>Mon</span><span>Wed</span><span>Fri</span><span>Sun</span></div></div> : <div className="rb-data-metrics"><ReferenceMetric label="Records" value="12,482" detail="+8.4%" tone="success" /><ReferenceMetric label="Latency" value="1.24s" detail="−12ms" /><ReferenceMetric label="Status" value="Healthy" detail="all systems" tone="running" /></div>}<ReferenceList>{rows.map((row, index) => <ReferenceListRow key={row} title={row} meta={`${index + 1} · ${variant === 8 ? 'wide table row' : 'updated just now'}`} selected={selected === row} onClick={() => setSelected(row)} badge={<ReferenceBadge tone={index === 0 ? 'success' : 'neutral'}>{index === 0 ? 'active' : 'ready'}</ReferenceBadge>} />)}</ReferenceList></ReferenceSurface>
}

export function FormBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const [saved, setSaved] = useState(false)
  const [open, setOpen] = useState('General')
  const sections = variant % 3 === 0 ? ['General', 'Permissions', 'Danger zone'] : ['Profile', 'Preferences', 'Review']
  return <ReferenceSurface className="rb-blueprint rb-form-blueprint" onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={definition} icon={definition.category === 'notifications' ? <Activity size={14} /> : <Settings2 size={14} />} tone={saved ? 'success' : 'neutral'} /><div className="rb-form-layout"><nav className="rb-form-sections">{sections.map((section) => <button type="button" key={section} className={open === section ? 'selected' : ''} onClick={() => setOpen(section)}>{section}<ChevronDown size={11} /></button>)}</nav><form className="rb-form-fields" onSubmit={(event) => { event.preventDefault(); setSaved(true) }}><label>Display name<input defaultValue="Meridian workspace" /></label><label>Scope<select defaultValue="Workspace"><option>Workspace</option><option>Session</option></select></label><label className="rb-form-switch"><input type="checkbox" defaultChecked /><span>Enable {open.toLocaleLowerCase()} notifications</span></label><div className="rb-form-footer"><small>{saved ? 'Saved just now' : 'Unsaved changes'}</small><ReferenceButton variant="secondary" type="button" onClick={() => setSaved(false)}>Reset</ReferenceButton><ReferenceButton variant="primary" type="submit">Save changes</ReferenceButton></div></form></div></ReferenceSurface>
}

export function EmptyBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const [retried, setRetried] = useState(false)
  const copy = variant === 1 ? ['No workspace data yet', 'Create a workspace or connect an existing project to get started.'] : variant === 2 ? ['No results found', 'Try a broader search or remove one of the active filters.'] : variant === 3 ? ['All caught up', 'There are no outstanding items requiring your attention.'] : variant === 4 ? [retried ? 'Loaded successfully' : 'Unable to load', retried ? 'The request completed after retrying.' : 'The public fixture records a recoverable request failure.'] : ['Drop files to begin', 'Drag a file here or choose one from your workspace.']
  return <ReferenceSurface className={`rb-blueprint rb-empty-blueprint rb-empty-blueprint-${variant}`} onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={definition} icon={variant === 4 ? <AlertTriangleIcon /> : variant === 5 ? <UploadIcon /> : <CircleDashed size={14} />} tone={variant === 4 && !retried ? 'danger' : 'neutral'} actions={false} /><ReferenceEmptyState title={copy[0]!} description={copy[1]!} action={<div className="rb-empty-actions"><ReferenceButton variant="primary" onClick={() => setRetried(true)}>{variant === 4 ? 'Retry' : variant === 5 ? 'Choose file' : 'Get started'}</ReferenceButton>{variant === 2 && <ReferenceButton variant="ghost">Clear filters</ReferenceButton>}</div>} />{variant === 5 && <div className="rb-dropzone-hint"><UploadIcon /> Supported formats · max size follows Host limits</div>}</ReferenceSurface>
}

function AlertTriangleIcon() { return <AlertTriangle size={14} /> }
function UploadIcon() { return <Upload size={14} /> }

export function WorkflowBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const variant = indexOf(definition)
  const [active, setActive] = useState(0)
  const items = ['Prepare', 'Review', 'Run', 'Complete']
  return <ReferenceSurface className="rb-blueprint rb-workflow-blueprint" onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={definition} icon={definition.category === 'kanban' ? <GripVertical size={14} /> : definition.category === 'editor' ? <File size={14} /> : <GitBranch size={14} />} tone={active === 3 ? 'success' : 'running'} /><div className="rb-workflow-rail">{items.map((item, index) => <button type="button" key={item} className={index === active ? 'active' : index < active ? 'done' : ''} onClick={() => setActive(index)}><span>{index < active ? <Check size={11} /> : index + 1}</span>{item}</button>)}</div><div className="rb-workflow-body">{definition.category === 'kanban' ? <div className="rb-kanban-columns">{['Queued', 'Running', 'Done'].map((column, columnIndex) => <div className="rb-kanban-column" key={column}><header><strong>{column}</strong><small>{columnIndex + 1}</small></header><ReferenceList>{['Inspect workspace', 'Review changes'].slice(0, columnIndex === 2 ? 1 : 2).map((item) => <ReferenceListRow key={`${column}-${item}`} title={item} meta={columnIndex === 1 ? 'active · 3 tools' : 'step'} />)}</ReferenceList></div>)}</div> : <><div className="rb-workflow-summary"><h3>{variant % 2 === 0 ? 'Review and confirm' : 'Workspace setup'}</h3><p>Each step keeps its state visible and offers a direct next action.</p></div><ReferenceButton variant={active === 3 ? 'secondary' : 'primary'} onClick={() => setActive((value) => Math.min(items.length - 1, value + 1))}>{active === 3 ? 'Completed' : 'Continue'} <ArrowDown size={12} /></ReferenceButton></>}</div></ReferenceSurface>
}

export function GenericBlueprint({ definition, onInteraction }: ReferenceFixtureProps) {
  const [tab, setTab] = useState('Overview')
  return <ReferenceSurface className="rb-blueprint rb-generic-blueprint" onClickCapture={(event) => reportFixtureClick(event, onInteraction)}><FixtureHeader definition={definition} icon={<WandSparkles size={14} />} /><ReferenceTabs tabs={['Overview', 'Details', 'Activity']} value={tab} onChange={setTab} /><div className="rb-generic-blueprint-body"><ReferenceEmptyState title={`${tab} surface`} description="Deterministic clean-room fixture with the same information hierarchy and responsive surface language." action={<ReferenceButton variant="primary"><Plus size={12} /> Add item</ReferenceButton>} /></div></ReferenceSurface>
}

export function ReferenceBlueprint({ definition, viewport, onInteraction, refreshKey }: ReferenceFixtureProps) {
  void viewport
  void onInteraction
  void refreshKey
  if (definition.category === 'agent-activity' || definition.category === 'monitoring') return <ActivityBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'tool-calls') return <ToolCallsBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'agent-approval') return <ApprovalBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'agent-plan') return <PlanBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'ai-usage') return <UsageBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'app-shell' || definition.category === 'app-sidebar' || definition.category === 'command-menu' || definition.category === 'navbar' || definition.category === 'mobile') return <ShellBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (['card', 'data-table', 'dashboard', 'analytics', 'list', 'filtering', 'file-manager'].includes(definition.category)) return <DataBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (['settings-form', 'forms', 'app-dialog', 'notifications', 'onboarding', 'paywall', 'authentication'].includes(definition.category)) return <FormBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (definition.category === 'empty-state') return <EmptyBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  if (['kanban', 'wizard', 'comments', 'scheduling', 'integrations', 'editor', 'feedback', 'support', 'billing', 'chat'].includes(definition.category)) return <WorkflowBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
  return <GenericBlueprint definition={definition} viewport={viewport} onInteraction={onInteraction} />
}
